module div_8bit (
    input wire clk,
    input wire rst,
    input wire [7:0] dividend,
    input wire [7:0] divisor,
    input wire sign,
    input wire opn_valid,
    output reg res_valid,
    input wire res_ready,
    output reg [15:0] result
);

reg [9:0] neg_divisor;
reg [7:0] dividend_reg, divisor_reg;
reg [16:0] sr;
reg [3:0] cnt;
reg start_cnt;

always@(posedge clk or posedge rst) begin
    if(rst) begin
        neg_divisor <= 0;
        dividend_reg <= 0;
        divisor_reg <= 0;
        sr <= 0;
        cnt <= 0;
        start_cnt <= 0;
    end
    else begin
        case({sign, opn_valid})
            2'b01: begin
                dividend_reg <= dividend;
                divisor_reg <= divisor;
                sr <= {1'b0, dividend[7], dividend}; 
                neg_divisor <= ~{1'b0, divisor} + 1; 
                cnt <= 1;
                start_cnt <= 1;
            end
            2'b11: begin
                dividend_reg <= dividend;
                divisor_reg <= divisor;
                sr <= {1'b0, dividend[7], dividend}; 
                neg_divisor <= ~{1'b0, divisor} + 1; 
                cnt <= 1;
                start_cnt <= 1;
            end
            default: begin
                start_cnt <= 0;
            end
        endcase
        if(start_cnt && !cnt[3]) begin
            if(cnt == 8) begin
                cnt <= 0;
                start_cnt <= 0;
                sr <= {sr[15:8] - neg_divisor[7:0], sr[7:0]};
                result <= {sr[15:8], sr[7:0]};
            end
            else begin
                sr <= {sr[15:8] - neg_divisor[7:0], sr[7:0]};
                cnt <= cnt + 1;
            end
        end
    end
end

always@(*) begin
    if(res_ready) begin
        res_valid = 0;
    end
    else if(cnt == 8) begin
        res_valid = 1;
    end
    else begin
        res_valid = res_valid;
    end
end

endmodule
